@startuml

enum RoomType {
  SINGLE
  DOUBLE
  TWIN
}

enum PaymentType {
  PREPAID
  PAID_AT_HOTEL
}

class HotelBookingManager {}

class Traveller {
  + name : string
  + reliabilityRating : int
}

class BillingInformation {
  + companyName : string
  + address : string
}

class TravelPreference {
  + preference : string
}

class Hotel {
  + city : string
  + address : string
}

class HotelChain {}

class RoomAvailability {
  + roomType : RoomType
  + isFullyBooked : boolean
}

class Search {
  + city : string
  + arrivalDate : date
  + departureDate : date
  + numberOfRooms : int
  + roomType : RoomType
  + minimumRating : int
  + budgetPerNight : float
}

class Booking {
  + bookingId : int
  + price : float
  + cityArea : string
  + hotelRating : int
  + cancellationDeadline : date
  + creditCardInformation : string
  + paymentType : PaymentType
  + isConfirmed : boolean
}

class SpecialOffer {
  + price : float
}

class PreliminaryBookingInfo {
  + price : float
  + cityArea : string
  + hotelRating : int
  + bookingId : int
}

Traveller "1" -- "*" Booking : makes
Traveller "1" -- "1" BillingInformation : provides
Traveller "1" -- "*" TravelPreference : specifies
Traveller "1" -- "*" Search : performs
Traveller "1" -- "*" SpecialOffer : receives

HotelBookingManager "1" -- "*" Traveller : manages
HotelBookingManager "1" -- "*" Hotel : lists
HotelBookingManager "1" -- "*" Booking : stores
HotelBookingManager "1" -- "*" PreliminaryBookingInfo : forwards
HotelBookingManager "1" -- "*" SpecialOffer : sends

Hotel "1" -- "*" RoomAvailability : announces
Hotel "1" -- "*" Booking : confirms
Hotel "0..1" -- "1" HotelChain : run by

Booking "1" -- "1" RoomAvailability : for
Booking "1" -- "1" Hotel : at
Booking "0..1" -- "1" SpecialOffer : switches to

PreliminaryBookingInfo "*" -- "1" Hotel : sent to
PreliminaryBookingInfo "1" -- "1" Search : based on
PreliminaryBookingInfo "1" -- "1" Traveller : for

SpecialOffer "*" -- "1" PreliminaryBookingInfo : competes with

@enduml

